import{_ as e,o as a,c as r,a3 as o}from"./chunks/framework.D3oaa6bG.js";const c=JSON.parse('{"title":"Products and Variants","description":"","frontmatter":{},"headers":[],"relativePath":"guide/usage/products.md","filePath":"guide/usage/products.md","lastUpdated":null}'),d={name:"guide/usage/products.md"};function n(s,t,i,h,p,u){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="products-and-variants" tabindex="-1">Products and Variants <a class="header-anchor" href="#products-and-variants" aria-label="Permalink to &quot;Products and Variants&quot;">​</a></h1><p>A Product is the central entity in <code>wn-mall-plugin</code>.</p><p>A Product has predefined properties like a price, a description or a stock value. It belongs to a category and brand, it provides downloads or can be made customizable by the end-user with custom fields. For simple goods this will be all you need.</p><p>If you sell goods with more complex properties, you can make use of Variants. Variants belong to a parent Product. They inherit every property of this Product except the one that are explicitly changed.</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p>The following examples help to illustrate the concept of Products and Variants.</p><table tabindex="0"><thead><tr><th>Type</th><th>Good</th><th>Can be bought directly</th></tr></thead><tbody><tr><td>Product</td><td>Your band&#39;s new record on CD</td><td>Yes</td></tr><tr><td></td><td></td><td></td></tr><tr><td>Product</td><td>Your band&#39;s new record on Vinyl</td><td>Yes</td></tr><tr><td></td><td></td><td></td></tr><tr><td>Product</td><td>Your band&#39;s new fan shirt</td><td>No</td></tr><tr><td>Variant</td><td>Your band&#39;s new fan shirt in Size S</td><td>Yes</td></tr><tr><td>Variant</td><td>Your band&#39;s new fan shirt in Size M</td><td>Yes</td></tr><tr><td>Variant</td><td>Your band&#39;s new fan shirt in Size L</td><td>Yes</td></tr></tbody></table><p>The music record on CD and Vinyl is handled as two different products. You cannot buy them in different colors or sizes. Each product has its own stock.</p><p>The fan shirt is available in three different sizes. The Variants share all the same properties as the Product has, except for their size. Each Variant has its own stock value. The stock value of the Product is the sum of all Variant&#39;s stock values.</p><p>If a Product has Variants you cannot buy the Product itself, only its Variants.</p><h2 id="inventory-management-method" tabindex="-1">Inventory Management Method <a class="header-anchor" href="#inventory-management-method" aria-label="Permalink to &quot;Inventory Management Method&quot;">​</a></h2><p>The Inventory Management Method defines if your Product is a &quot;simple Product&quot; or is sold as different Variants.</p><h2 id="group-by-property" tabindex="-1">Group by property <a class="header-anchor" href="#group-by-property" aria-label="Permalink to &quot;Group by property&quot;">​</a></h2><p>This option allows you to define a property that makes your Variants unique.</p><p>Let&#39;s say you have a T-Shirt that is available in the sizes S, M and L and the colors blue and red. In this case you want to group by color since this makes the Variants unique.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><p>The <a href="./properties.html">Properties</a> a Product or Variant has are defined by the <a href="./categories.html">Category</a> they belong to.</p><p>Define your Property groups and Categories before you create any products.</p>',18)])])}const y=e(d,[["render",n]]);export{c as __pageData,y as default};
